"""Replay backend tests, using fake 'recordings' generated by the simulator
(so they run without Docker)."""
import json

import numpy as np
import pytest

from faultdiag.agents.evaluate import run_episodes
from faultdiag.baselines import BASELINES
from faultdiag.env import DiagModel, EnvConfig, FaultDiagEnv
from faultdiag.env.constants import N_FAULTS, N_REPAIRS, N_SOURCES, NO_FAULT, TELEMETRY
from faultdiag.env.replay import ReplayBackend
from faultdiag.testbed.record import calibrate


def fake_recordings(path, trials=6, repeats=3, seed=0):
    model, rng = DiagModel(), np.random.default_rng(seed)
    with open(path, "w") as f:
        for t in range(trials):
            split = "test" if t == trials - 1 else "train"
            for fault in range(N_FAULTS):
                for sev in (0, 1):
                    answers = [[model.sample_label(k, fault, sev, rng) for _ in range(repeats)]
                               for k in range(N_SOURCES)]
                    f.write(json.dumps({"kind": "obs", "split": split, "fault": fault,
                                        "severity": sev, "trial": t, "answers": answers}) + "\n")
            for fault in range(1, N_FAULTS):
                for r in range(N_REPAIRS):
                    f.write(json.dumps({"kind": "repair", "split": split, "fault": fault, "severity": 1,
                                        "repair": r, "fixed": model.sample_repair(r, fault, rng)}) + "\n")


@pytest.fixture
def rec(tmp_path):
    p = tmp_path / "recordings.jsonl"
    fake_recordings(p)
    obs, success, _, _ = calibrate(p, "train")
    cal = tmp_path / "calibrated.json"
    cal.write_text(json.dumps({"obs": obs.tolist(), "success": success.tolist()}))
    return str(p), str(cal)


def test_answers_are_replayed_in_order(rec):
    path, _ = rec
    be = ReplayBackend(path, "train")
    rng = np.random.default_rng(1)
    be.start_incident(3, 1, rng)
    recorded = be.current[TELEMETRY]
    got = [be.query(TELEMETRY, rng) for _ in range(len(recorded))]
    assert got == recorded


def test_test_split_is_separate(rec):
    path, _ = rec
    tr, te = ReplayBackend(path, "train"), ReplayBackend(path, "test")
    n_tr = sum(len(v) for v in tr.incidents.values())
    n_te = sum(len(v) for v in te.incidents.values())
    assert n_tr == 5 * N_FAULTS * 2 and n_te == N_FAULTS * 2


def test_calibration_is_a_valid_model(rec):
    _, cal = rec
    m = DiagModel.from_file(cal)
    assert np.allclose(m.obs.sum(axis=-1), 1.0)
    assert (m.success[NO_FAULT] == 0).all()


def test_env_runs_on_replayed_data(rec):
    path, cal = rec
    cfg = EnvConfig(replay_file=path, replay_split="train", sources_file=cal)
    env = FaultDiagEnv(cfg)
    assert isinstance(env.backend, ReplayBackend)
    rng = np.random.default_rng(0)
    for ep in range(100):
        env.reset(seed=ep)
        done = False
        while not done:
            _, _, done, _, info = env.step(rng.choice(np.flatnonzero(env.action_masks())))
    assert "outcome" in info


@pytest.mark.parametrize("name", ["never_acquire", "greedy_voi", "act_then_measure"])
def test_baselines_on_replayed_test_split(rec, name):
    path, cal = rec
    cfg = EnvConfig(replay_file=path, replay_split="test", sources_file=cal)
    rows = run_episodes(BASELINES[name](), cfg, 30)
    assert all(np.isfinite(r["return"]) for r in rows)
